function getCookie(e){var t=null;if(document.cookie&&""!=document.cookie)for(var a=document.cookie.split(";"),n=0;n<a.length;n++){var r=jQuery.trim(a[n]);if(r.substring(0,e.length+1)==e+"="){t=decodeURIComponent(r.substring(e.length+1));break}}return t}function csrfSafeMethod(e){return/^(GET|HEAD|OPTIONS|TRACE)$/.test(e)}function PartnerSearch(){var e=$("#id_url").attr("data-url");partner_name=$("#id_partner_name").val();const t=$("#id_partner");t.children().remove(),$.ajax({url:e,type:"GET",data:{partner_name:partner_name},dataType:"json"}).done(function(e){for(const a of e.partner_list){const e=$("<option>");e.val(a.name),t.append(e)}var a=[];for(const t of e.partner_list)a.push(t.name);alert(a),$("#id_partner_name").autocomplete({source:a,autoFocus:!0,delay:500,minLength:2})}).fail(function(e,t,a){alert(t+":"+a)}),$("#id_partner_name").trigger("click")}function PartnerPopup(){var e=$("#id_url").attr("data-url");partner_name=$("#id_partner_name").val();var t=$("#id_partner");t.children().remove(),$.ajax({url:e,type:"GET",data:{partner_name:partner_name},dataType:"json"}).done(function(e){for(var a of e.partner_list){var n=$("<option>");n.val(a.id),n.text(a.name),t.append(n)}var r=$("#id_partner_name").width();$("#modal_dialog").dialog({dialogClass:"partnerDialog",position:{my:"left top",at:"left bottom",of:"#id_partner_name"},width:r,buttons:{"閉じる":function(){$(this).dialog("close")}}})}).fail(function(e,t,a){alert(t+":"+a)})}function ClosePartnerPopup(){$("#modal_dialog").dialog("close")}var csrftoken=getCookie("csrftoken");$.ajaxSetup({beforeSend:function(e,t){csrfSafeMethod(t.type)||this.crossDomain||e.setRequestHeader("X-CSRFToken",csrftoken)}}),$(document).on("click",function(e){$(e.target).closest("#modal_dialog").length||$("#modal_dialog").dialog("close")});